const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rub=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const P=DATA.products;const priced=P.filter(p=>p.price);const allCategories=DATA.categories;
function saved(k,d){try{return JSON.parse(localStorage.getItem('champion-'+k))??d}catch{return d}}
let cart=saved('cart',{}),favs=saved('favs',[]),compare=[],qty=1,limit=12,filters={},selectedTab='description',listingItems=[],listingTitle='';
const statusLabels={catalog:'Каталожная позиция',transit:'В пути · без продажи',future:'Планируется',review:'Данные уточняются'};
const series=[
 {key:'pobeda',name:'Победа',kind:'Магнитная система · 48 В',desc:'Светильники, шинопроводы, питание и управление. Исполнения Про и Эко в одной линейке.',image:'assets/3-modules0-media.webp',tag:'Про / Эко',category:allCategories[0]},
 {key:'olimpika',name:'Олимпика',kind:'Встраиваемые модульные светильники',desc:'Светодиодный модуль, монтажная рамка и драйвер. Оптика и аксессуары — по составу изделия.',image:'assets/3-modules2-media.webp',tag:'Модульная конструкция',category:'Встраиваемые модульные светильники'},
 {key:'evrotrek',name:'Евротрек',kind:'Трёхфазная трековая система · 220 В',desc:'Шинопроводы, соединения и компоненты для трёхфазной трековой системы.',image:'assets/3-modules4-media.webp',tag:'Трёхфазный трек',category:'Трёхфазные трековые системы 220 В'}
];
const faq=[
 ['Как заказать, если артикулы уже известны?','Найдите позиции в каталоге, добавьте количество в список заказа и подготовьте запрос. ChampionLED уточняет актуальные цену, наличие, сроки и условия поставки. В этом прототипе запрос можно проверить и скачать, отправка отключена.'],
 ['Чем отличаются «Победа Про» и «Победа Эко»?','Это исполнения магнитной линейки «Победа». Эко использует более простой встраиваемый конструктив и базовую геометрию. Про включает разные варианты монтажа и геометрии. Состав и условия применения проверяют по документации конкретной системы.'],
 ['Из чего состоит светильник «Олимпика»?','Из светодиодного модуля с базовым рефлектором, монтажной рамки и драйвера. Сменная оптика и аксессуары расширяют варианты исполнения. Цена одного компонента не является ценой полного светильника.'],
 ['Где найти инструкции, размеры и фотометрию?','В разделе «Документация» и материалах конкретной серии. В прототип включены предоставленные PDF для «Победа Про», «Победа Эко» и «Олимпика». Наличие IES, 3D и других файлов проверяется по модели; универсальная библиотека для всего каталога не заявляется.'],
 ['Кто поможет выбрать свет под объект?','Подбор мощности, оптики, управления, расчёт по плану, проверку конфигурации, адаптацию и монтаж ведёт LEDMONSTER. ChampionLED оформляет заказ определённых позиций и предоставляет стандартные сведения о продукции.'],
 ['Какая гарантия на продукцию?','На изделия ChampionLED действует гарантия 3 года, в том числе при покупке в составе проекта LEDMONSTER. Порядок обращения и упрощённой замены неисправных изделий определяется гарантийными условиями.'],
 ['Можно ли заказать позиции со статусом «Планируется»?','Такие позиции показаны только как направление развития ассортимента по товарной матрице. Они не добавляются в заказ. Срок запуска и итоговые параметры требуют отдельного подтверждения.']
];
const crumb=(arr=[])=>`<div class="breadcrumb"><a href="#/">Главная</a>${arr.map(([s,h])=>`<span>/</span>${h?`<a href="${h}">${esc(s)}</a>`:`<span>${esc(s)}</span>`}`).join('')}</div>`;
const btn=(label,href,cls='primary')=>`<a class="button ${cls}" href="${href}">${label}<span class="arrow">↗</span></a>`;
const tag=p=>`<span class="status ${p.status}">${statusLabels[p.status]}</span>`;
const sectionHead=(k,t,right='')=>`<div class="section-head"><div><p class="eyebrow">${k}</p><h2>${t}</h2></div>${right}</div>`;
function persist(){try{localStorage.setItem('champion-cart',JSON.stringify(cart));localStorage.setItem('champion-favs',JSON.stringify(favs))}catch{}counts()}
function counts(){$('#cart-count').textContent=Object.values(cart).reduce((a,b)=>a+b,0);$('#fav-count').textContent=favs.length}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
function closeModal(){$('#modal').close()}
function download(name,text,type='text/csv;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function add(id,n=1){const p=P.find(x=>x.id===id);if(!p||p.status!=='catalog')return;cart[id]=Math.min(999,(cart[id]||0)+n);persist();toast('Позиция добавлена в список заказа')}
function seriesTile(s){return `<a class="series-tile" href="#/series/${s.key}"><div class="series-photo"><img src="${s.image}" alt="${s.name} — изображение серии ChampionLED" loading="lazy"></div><div class="series-body"><small>${s.kind}</small><h3>${s.name}</h3><p>${s.desc}</p><div class="tile-bottom"><span>${s.tag}</span><span>↗</span></div></div></a>`}
function productCard(p){return `<article class="product"><div class="product-picture"><a href="#/product/${p.id}" aria-label="Открыть ${esc(p.name)}">${p.images?`<img src="${p.images[0]}" alt="${esc(p.name)}" loading="lazy">`:`<div class="no-photo"><span>⊙</span>${esc(p.type||'Компонент')}<small>Фото уточняется</small></div>`}</a><button class="favourite ${favs.includes(p.id)?'active':''}" data-fav="${p.id}" aria-label="${favs.includes(p.id)?'Удалить из избранного':'В избранное'}" aria-pressed="${favs.includes(p.id)}">${favs.includes(p.id)?'♥':'♡'}</button><span class="tag">${p.status==='catalog'?esc(p.series==='Победа'?'Победа · 48 В':p.series):statusLabels[p.status]}</span></div><div class="product-meta"><small>${esc(p.sku||'Артикул не присвоен')}</small><a href="#/product/${p.id}"><h3>${esc(p.short||p.name)}</h3></a><p>${p.power?`${p.power} Вт · 3000 / 4000 К · чёрный`:esc(p.type||p.category)}</p><div class="price-row"><strong>${p.price?rub(p.price):p.status==='catalog'?'Цена по запросу':p.status==='review'?'Состав уточняется':p.status==='transit'?'В пути':'Планируется'}</strong>${p.status==='catalog'?`<button data-add="${p.id}" aria-label="Добавить ${esc(p.short||p.name)} в список заказа">+</button>`:`<a class="textlink" href="#/product/${p.id}">Подробнее</a>`}</div>${p.price?`<label class="compare-check"><input type="checkbox" data-compare="${p.id}" ${compare.includes(p.id)?'checked':''}> Сравнить</label>`:''}</div></article>`}
function faqs(items=faq){return `<div class="faqs">${items.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`}
function projectBlock(){return `<div class="project-block"><div><div class="project-logo">LED<span>MONSTER</span></div><h2>Когда нужен свет<br>под конкретный объект</h2></div><div><p>Подбор, светотехнический расчёт, конфигурация системы, адаптация и реализация — задачи проектной команды LEDMONSTER. Изделия ChampionLED сохраняют свою марку и гарантию.</p>${btn('Обсудить проектную задачу','#/project','dark')}</div></div>`}
function home(){return `<div class="wrap"><section class="hero"><div class="hero-copy"><p class="eyebrow">ChampionLED · стандартный продукт</p><h1>Продуманный свет.<br><span>Рациональный<br>выбор.</span></h1><p class="lead">Функциональные светильники и системы с инженерной проработкой, качественными комплектующими и доступной ценой.</p><div class="actions">${btn('Смотреть каталог','#/catalog')}${btn('Изучить линейки','#/series','')}</div><div class="hero-foot"><span>3</span><span>года гарантии<br>на изделия ChampionLED</span></div></div><div class="hero-image"><img src="assets/1-backgroundImage.webp" alt="Интерьер с трековыми светильниками ChampionLED"><div class="hero-side">Ценность заложена в продукте<b>До его покупки.</b></div><a class="hero-caption" href="#/series/pobeda"><div><small>ЗНАКОМЬТЕСЬ С ЛИНЕЙКОЙ</small><h3>Победа</h3><small>Магнитная система 48 В · Про и Эко</small></div><span class="round-arrow">↗</span></a></div></section><div class="trust-row"><div><b>↗</b><p><strong>Инженерная основа</strong>Проработка серийного продукта</p></div><div><b>◎</b><p><strong>Понятный состав</strong>Изделие и компоненты системы</p></div><div><b>≡</b><p><strong>Технические данные</strong>Параметры и документация</p></div><div><b>✓</b><p><strong>Ответственность бренда</strong>Контроль и гарантия 3 года</p></div></div><section class="section">${sectionHead('Свои линейки','Системы, в которых<br>всё связано.',`<a class="textlink" href="#/series">Все линейки и их состав ↗</a>`)}<div class="series-grid">${series.map(seriesTile).join('')}</div><p class="fine">Изучите состав линейки и варианты исполнения. Параметры и наличие проверяются по конкретным позициям.</p></section><section class="splitband"><div><small>01 / Самостоятельная закупка</small><h3>Уже знаете,<br>что нужно заказать?</h3><p>Найдите позиции по артикулу или соберите список из каталога. Уточним стоимость, наличие и условия поставки.</p>${btn('Подготовить список заказа','#/catalog','dark')}</div><div><small>02 / Профессиональное сотрудничество</small><h3>Свет для вашего<br>торгового предложения</h3><p>Ассортимент, товарные материалы и закупка определённых позиций — для дилеров и торговых партнёров.</p>${btn('Условия сотрудничества','#/professionals/dealer','')}</div></section><section class="section">${sectionHead('Изучите продукт','Светильники линейки «Победа»',`<a class="textlink" href="#/catalog/svetilniki-pobeda-pro">Все светильники линейки ↗</a>`)}<div class="product-grid">${[priced[1],priced[0],priced[2],priced[4]].map(productCard).join('')}</div><p class="fine">Цены — снимок действующего сайта на 01.11.2026 для показанного исполнения ON-OFF. Актуальные условия подтверждаются при заказе.</p></section></div><section class="technical-band"><div class="technical-inner wrap"><div><p class="eyebrow">За внешним видом — конструкция</p><h2>Техническая ясность.<br>До закупки и монтажа.</h2><p>Изучайте не только внешний вид светильника. Важны его устройство, параметры и полный состав рабочего изделия.</p>${btn('Открыть документацию','#/materials','light')}</div><div class="technical-points"><div><span>01 / Параметры</span><b>Что даёт свет</b><small>Мощность, световые параметры и исполнения по конкретной модели.</small></div><div><span>02 / Комплектность</span><b>Из чего состоит изделие</b><small>Световая часть, монтаж, питание и предусмотренные опции.</small></div><div><span>03 / Монтаж</span><b>Как устроена система</b><small>Инструкции и схемы для соответствующей серии.</small></div><div><span>04 / Ответственность</span><b>Кто стоит за продуктом</b><small>Требования бренда, контроль производства и гарантия 3 года.</small></div></div></div></section><div class="wrap"><section class="section">${sectionHead('Работаете со светом?','Материалы для вашей задачи')}<div class="audience-grid"><a href="#/professionals/dealer"><small>01 / Закупка и перепродажа</small><h3>Дилерам</h3><p>Ассортимент, товарные данные и коммерческие условия.</p><span>Обсудить сотрудничество ↗</span></a><a href="#/professionals/designer"><small>02 / Выбор и спецификация</small><h3>Дизайнерам и архитекторам</h3><p>Исполнения, параметры и материалы для включения в проект.</p><span>Изучить возможности ↗</span></a><a href="#/professionals/installer"><small>03 / Подготовка к монтажу</small><h3>Подрядчикам и интеграторам</h3><p>Состав, инструкции, питание и управление по документации.</p><span>Открыть технические материалы ↗</span></a></div></section>${projectBlock()}<section class="section">${sectionHead('Перед заказом','Ответы на основные вопросы',`<a class="textlink" href="#/faq">Все вопросы ↗</a>`)}${faqs(faq.slice(0,4))}</section></div>`}
function catDisplay(c){return ({'СВЕТОДИОДНАЯ ЛЕНТА':'Светодиодная лента','Магнитные системы 48 В РИТЕЙЛ КОНСТРУКТУР':'Магнитные пространственные системы 48 В','Настенные светильники (Бра)':'Настенные светильники','Распродажа':'Распродажа'})[c]||c}
function catGrid(){return `<div class="catalog-category-grid">${allCategories.map((c,i)=>{const ps=P.filter(p=>p.category===c);if(c==='Распродажа')return `<a class="category-entry" href="#/service"><div>Распродажа<small>Специальная подборка · состав уточняется</small></div><span>↗</span></a>`;const names=[...new Set(ps.map(x=>x.series))].filter(x=>x&&!/название|светильники|питания|управление|профиль|светодиодная|по типу/i.test(x));const available=ps.some(x=>x.status==='catalog');return `<a class="category-entry" href="#/catalog/matrix-${i}"><div>${esc(catDisplay(c))}<small>${names.length?esc(names.join(' · ')):available?'Позиции и компоненты':'Направление развития'}${!available?' · без продажи':''}</small></div><span>↗</span></a>`}).join('')}</div>`}
function seriesPage(key){const s=series.find(x=>x.key===key);if(!s)return `<div class="wrap section">${crumb([['Наши линейки']])}<h1 class="page-title">Наши линейки</h1><p class="page-intro">Собственная линейка объединяет связанные изделия и компоненты. Категории помогают найти тип продукта, линейки — понять систему и её состав.</p><div class="series-grid" style="margin-top:35px">${series.map(seriesTile).join('')}</div><section class="section">${sectionHead('Развитие ассортимента','Следующие направления')}<div class="upcoming"><div><span class="status transit">В пути · без продажи</span><h3>Линия</h3><p>Линейные системы. В матрице — «ЛИНИЯ 57», стандартное решение в пути. Итоговые параметры и запуск уточняются.</p><a class="textlink" href="#/catalog/matrix-2">Посмотреть направление ↗</a></div><div><span class="status transit">В пути · без продажи</span><h3>Импульс</h3><p>Гибридные светильники. Модель «Атом» заказана и в пути. Состав исполнений и дата начала продаж уточняются.</p><a class="textlink" href="#/catalog/matrix-6">Посмотреть направление ↗</a></div></div><p class="notice">«Легенда» — планируемая линейка магнитных пространственных систем 48 В. В матрице требуется решение; к покупке не предлагается. «Марафон» сохранён в текущем меню сайта, но не включён в подтверждённые этой матрицей линейки.</p></section></div>`;
 const olimp=key==='olimpika';const parts=olimp?[['Модуль','Светодиодный модуль с базовым рефлектором.'],['Рамка','Монтажная часть: форма, цвет, поворот и способ установки.'],['Драйвер','Питание и предусмотренное управление.'],['Опции','Сменные линзы, сетка и декоративные элементы.']]:key==='pobeda'?[['Шинопровод','Геометрия и монтаж в исполнении Про или Эко.'],['Светильники','Модули общего и направленного света.'],['Питание','Блок питания и элементы подключения системы.'],['Соединения и управление','Компоненты соответствующего исполнения.']]:[['Шинопровод','Накладные трёхфазные шинопроводы.'],['Соединения','Прямые, угловые и другие каталожные элементы.'],['Подключение','Питание и принадлежности трека.'],['Монтаж','Подвесы, заглушки и усилители стыка.']];
 return `<div class="wrap">${crumb([['Наши линейки','#/series'],[s.name]])}<section class="series-hero"><div><p class="eyebrow">Собственная линейка ChampionLED</p><h1 class="page-title">${s.name}</h1><p class="page-intro">${s.desc}</p><div class="chips"><span class="chip">${s.kind}</span><span class="chip">Гарантия 3 года</span></div><div class="actions">${btn('Позиции линейки',`#/catalog/matrix-${allCategories.indexOf(s.category)}`)}${btn('Документация','#/materials','')}</div></div><img src="${s.image}" alt="Линейка ${s.name}"></section>${sectionHead('Понимайте систему целиком',olimp?'Один светильник — несколько компонентов':'Из чего складывается система')}<div class="steps-grid">${parts.map(([t,d],i)=>`<div><span>0${i+1}</span><b>${t}</b><p>${d}</p></div>`).join('')}</div><p class="notice">${olimp?'Рамка или модуль по отдельности — компонент, а не готовый светильник. Итоговая стоимость зависит от полного состава.':'Позиции заказываются отдельно. Состав определяется выбранными артикулами и документацией. Показ страницы не является проверкой конфигурации под объект.'}</p>${key==='pobeda'?`<section class="section"><div class="splitband"><div><small>Исполнение / Про</small><h3>Больше вариантов<br>монтажа и геометрии</h3><p>Накладные, встраиваемые и радиусные элементы — по товарной матрице.</p>${btn('Открыть «Победа Про»','#/catalog/pobeda-pro','dark')}</div><div><small>Исполнение / Эко</small><h3>Базовая геометрия.<br>Встраиваемый конструктив.</h3><p>Более простой встраиваемый конструктив с общей линейкой светильников «Победа».</p>${btn('Открыть «Победа Эко»','#/catalog/pobeda-eko','')}</div></div></section>`:''}<section class="section">${sectionHead('Товарный состав',olimp?'Компоненты «Олимпика»':`Позиции «${s.name}»`, `<a class="textlink" href="#/catalog/matrix-${allCategories.indexOf(s.category)}">Весь состав ↗</a>`)}<div class="product-grid">${(key==='pobeda'?priced.slice(0,4):P.filter(p=>p.category===s.category&&p.status==='catalog').slice(0,4)).map(productCard).join('')}</div></section>${projectBlock()}<div class="section"></div></div>`}
function findMenu(slug){let found;function walk(ns){for(const n of ns){if(n.url.replace('https://championled.ru','').split('/').pop()===slug)found=n;walk(n.children||[])}}walk(DATA.menu);return found}
function catalogContext(slug){if(!slug)return {title:'Каталог светильников и систем',items:P};if(slug.startsWith('matrix-')){const c=allCategories[Number(slug.slice(7))];return c?{title:catDisplay(c),items:P.filter(p=>p.category===c)}:{title:'Раздел не найден',items:[]}}const node=findMenu(slug),title=node?.title||'Каталог';let items=P;
 if(/pobeda/.test(slug)){items=P.filter(p=>p.series==='Победа');if(slug==='pobeda-eko')items=items.filter(p=>/ЭКО/i.test(p.name)||p.type==='Магнитный трековый светильник');else if(slug==='pobeda-pro')items=items.filter(p=>!/ЭКО/i.test(p.name));else if(slug.includes('svetilniki'))items=items.filter(p=>p.type==='Магнитный трековый светильник');else if(slug.includes('shinoprovody'))items=items.filter(p=>/Шинопровод|Угол шинопровода/.test(p.type)&&(/eko/.test(slug)?/ЭКО/.test(p.name):!/ЭКО/.test(p.name)));else if(/pitaniya|podklyuchenie/.test(slug))items=items.filter(p=>/питания/.test(p.type));else if(slug.includes('komplektuyshchie'))items=items.filter(p=>!/Магнитный трековый|Шинопровод|Блок питания/.test(p.type));}
 else if(slug.includes('olimpika')){items=P.filter(p=>p.series==='Олимпика');if(/bezram|bez-ram/.test(slug))items=items.filter(p=>/безрамоч/i.test(p.type));else if(slug!=='olimpika')items=items.filter(p=>/рамка/i.test(p.type)&&!/безрамоч/i.test(p.type));}
 else if(slug.includes('evrotrek')){items=P.filter(p=>p.series==='Евротрек');if(slug.includes('svetilniki'))items=items.filter(p=>/светильник/i.test(p.type));else if(slug.includes('treki-'))items=items.filter(p=>/Шинопровод трёхфазный/.test(p.type));else if(slug.includes('komplektuyshchie'))items=items.filter(p=>!/Шинопровод трёхфазный|светильник/i.test(p.type));}
 else if(slug.includes('marafon')||slug.includes('svetovye-dugi'))items=[];
 else if(slug==='sistemy-i-linejki')items=P.filter(p=>['Победа','Евротрек','Олимпика','Линия','Легенда','Импульс'].includes(p.series));
 else if(slug.includes('podvesnye'))items=[];
 else if(slug.includes('nastennye'))items=P.filter(p=>/Настенные/.test(p.category));
 else if(slug.includes('nakladnye'))items=P.filter(p=>p.category==='Накладные светильники');
 else if(slug.includes('vstraivaemye'))items=P.filter(p=>p.category==='Встраиваемые модульные светильники');
 else if(slug.includes('interernye'))items=P.filter(p=>!/Уличные/.test(p.category));
 return {title,items,missing:/marafon|svetovye-dugi/.test(slug)};}
function catalog(slug,query){const ctx=catalogContext(slug);if(ctx.items.length&&!ctx.items.some(p=>p.status==='catalog')&&query===undefined)filters.plans=true;listingItems=query!==undefined?P.filter(p=>(p.name+' '+p.sku+' '+p.series+' '+p.category).toLowerCase().includes(query.toLowerCase())):ctx.items;listingTitle=query!==undefined?`Поиск: ${esc(query)}`:esc(ctx.title);const types=[...new Set(listingItems.map(p=>p.type).filter(Boolean))];
 return `<div class="wrap"><div class="page-top">${crumb([['Каталог',slug?'#/catalog':null],...(slug?[[ctx.title]]:[])])}<h1 class="page-title">${listingTitle}</h1><p class="page-intro">${ctx.missing?'Раздел сохранён в меню действующего сайта. В новой товарной матрице состав «Марафон» не указан; позиции не подменены другими линейками.':'Категории — по типу продукта. Линейки — по связи изделий и компонентов. Изучите состав, определите артикулы и количество.'}</p>${!slug&&query===undefined?`<details><summary class="textlink" style="cursor:pointer">Категории светильников и компонентов ↗</summary>${catGrid()}</details>`:''}<div class="chips">${series.map(s=>`<a class="chip" href="#/series/${s.key}">${s.name} ↗</a>`).join('')}<a class="chip" href="#/materials">Инструкции и каталоги ↗</a></div></div><div class="catalog-layout"><aside class="filter-panel" id="filters"><h3>Состав ассортимента</h3><label><input type="checkbox" data-filter="plans" ${filters.plans?'checked':''}> Показать развитие ассортимента</label><h3>Товарная сущность</h3><select data-filter="type" aria-label="Товарная сущность"><option value="">Все типы</option>${types.map(t=>`<option value="${esc(t)}" ${filters.type===t?'selected':''}>${esc(t)}</option>`).join('')}</select><h3>Мощность светильника</h3>${[6,12,18,24].map(w=>`<label><input type="checkbox" data-power="${w}" ${(filters.power||[]).includes(w)?'checked':''}> ${w} Вт</label>`).join('')}<h3>Цена</h3><label><input type="checkbox" data-filter="priced" ${filters.priced?'checked':''}> Только с указанной ценой</label><button class="textlink" data-action="reset-filters">Сбросить фильтры</button><p class="filter-note">Параметры фильтра мощности подтверждены для шести показанных моделей. Цена и наличие уточняются при заказе. «Каталожная позиция» не означает наличие на складе.</p></aside><div><div class="listing-head"><span id="result-count"></span><button class="button mobile-filter" data-action="filters">Фильтры ☰</button><label>Сортировка <select id="sort" aria-label="Сортировка"><option value="default">Сначала с фото</option><option value="price-up">Цена по возрастанию</option><option value="price-down">Цена по убыванию</option><option value="name">По названию</option></select></label></div><div id="listing"></div><p class="notice">Цена, наличие и условия поставки подтверждаются по конкретным позициям. Планируемые товары и позиции в пути не включаются в заказ. Указанные цены зафиксированы на 01.11.2026.</p></div></div></div>`}
function filteredItems(){let ps=listingItems.filter(p=>filters.plans||p.status==='catalog');if(filters.type)ps=ps.filter(p=>p.type===filters.type);if(filters.priced)ps=ps.filter(p=>p.price);if(filters.power?.length)ps=ps.filter(p=>filters.power.includes(p.power));const sort=$('#sort')?.value||'default';return ps.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'ru'):sort==='price-up'?(a.price??Infinity)-(b.price??Infinity):sort==='price-down'?(b.price??-1)-(a.price??-1):Number(!!b.price)-Number(!!a.price)||a.row-b.row)}
function updateListing(){if(!$('#listing'))return;const ps=filteredItems();$('#result-count').textContent=`Найдено: ${ps.length} · показано ${Math.min(limit,ps.length)}`;$('#listing').innerHTML=ps.length?`<div class="product-grid listing-grid">${ps.slice(0,limit).map(productCard).join('')}</div>${ps.length>limit?'<button class="button loadmore" data-action="more">Показать ещё</button>':''}`:`<div class="empty"><h2>${listingItems.length?'В этой выборке нет позиций':'Состав раздела уточняется'}</h2><p>${listingItems.length?'Сбросьте фильтры или включите развитие ассортимента.':'По мере готовности здесь появятся модели, параметры и документы.'}</p><button class="button" data-action="reset-filters">Сбросить фильтры</button></div>`;compareBar()}
function productPage(id){const p=P.find(x=>x.id===id);if(!p)return notFound();qty=1;selectedTab='description';return `<div class="wrap">${crumb([['Каталог','#/catalog'],[p.series||p.category],[p.short||p.name]])}<section class="pdp"><div><div class="gallery-main" id="gallery">${p.images?`<img src="${p.images[0]}" alt="${esc(p.name)}">`:`<div class="no-photo"><span>⊙</span>${esc(p.type||'Изделие')}<small>Фотография уточняется</small></div>`}</div>${p.images?`<div class="thumbs">${p.images.map((src,i)=>`<button class="${!i?'active':''}" data-image="${src}" aria-label="Изображение ${i+1}"><img src="${src}" alt="${esc(p.short)} — ракурс ${i+1}"></button>`).join('')}</div>`:''}</div><div><p class="eyebrow">ChampionLED · ${esc(p.series)}</p><h1>${esc(p.short||p.name)}</h1><p class="subtitle">${esc(p.type||p.category)}</p><div class="sku-line"><span>Артикул ${esc(p.sku||'уточняется')}</span><span>Гарантия 3 года</span></div><div style="margin-top:18px">${tag(p)}</div>${p.images?`<dl class="specs"><div><dt>Мощность</dt><dd>${p.power} Вт</dd></div><div><dt>Цветовая температура</dt><dd>3000 / 4000 К</dd></div><div><dt>Напряжение системы</dt><dd>48 В</dd></div><div><dt>Исполнение</dt><dd>Чёрный · ON-OFF</dd></div></dl>`:`<dl class="specs"><div><dt>Категория</dt><dd>${esc(catDisplay(p.category))}</dd></div><div><dt>Состав / тип</dt><dd>${esc(p.type||'Уточняется')}</dd></div></dl>`}<div class="price">${p.price?rub(p.price):p.status==='catalog'?'Цена по запросу':'Без продажи'}<small>${p.price?'За 1 шт. · снимок цены на 01.11.2026':p.status==='catalog'?'Стоимость позиции и поставки уточняется':'Статус развития ассортимента по master v0.1'}</small></div>${p.status==='catalog'?`<div class="add-row"><div class="quantity"><button data-action="qty-minus" aria-label="Уменьшить количество">−</button><output id="qty">1</output><button data-action="qty-plus" aria-label="Увеличить количество">+</button></div><button class="button primary" data-add-qty="${p.id}">В список заказа <span>+</span></button></div>`:`<p class="notice">${p.status==='transit'?'Поставка в пути. Начало продаж и точный состав исполнений уточняются.':p.status==='future'?'Планируемая позиция. Итоговые название, параметры и дата запуска требуют подтверждения.':'Товарные данные требуют уточнения перед включением в предложение.'}</p>`}<div class="actions"><button class="textlink" data-fav="${p.id}">${favs.includes(p.id)?'♥ В избранном':'♡ Сохранить в избранное'}</button>${p.url?`<a class="textlink" href="${p.url}" target="_blank" rel="noopener">На действующем сайте ↗</a>`:''}</div><p class="fine">${p.images?`Цена относится к показанному исполнению. SKU предложения на действующем сайте: ${p.liveSku}. Доступность, управление и условия поставки подтверждаются отдельно.`:'Каталожные сведения не заменяют технический паспорт. Недостающие характеристики не рассчитаны и не восстановлены по аналогам.'}</p></div></section><div class="tabs" role="tablist" aria-label="Сведения о товаре"><button role="tab" aria-selected="true" class="active" data-tab="description" data-product="${p.id}">Описание и состав</button><button role="tab" aria-selected="false" data-tab="documents" data-product="${p.id}">Документация</button><button role="tab" aria-selected="false" data-tab="order" data-product="${p.id}">Заказ и гарантия</button></div><div id="product-tab" role="tabpanel">${productTab(p,'description')}</div><section class="section">${projectBlock()}</section></div>`}
function productTab(p,tab){if(tab==='documents')return `<div class="article"><h2>Материалы линейки</h2><p>Проверьте паспорт и состав конкретного исполнения. Ссылки ниже ведут на материалы серии; наличие IES, 3D и чертежей по позиции уточняется отдельно.</p>${btn('Открыть документацию','#/materials','')}</div>`;if(tab==='order')return `<div class="article"><h2>Покупка определённых позиций</h2><p>Укажите артикулы и количество. ChampionLED подтверждает цену, наличие, срок и условия поставки. На изделия действует гарантия 3 года; гарантийное обращение рассматривается по установленным условиям.</p><p>В прототипе доступен список заказа и экспорт CSV. Товарный заказ и оплата не выполняются.</p></div>`;return `<div class="article"><h2>${p.series==='Олимпика'?'Компонент модульного светильника':p.series==='Победа'?'Часть линейки «Победа»':'Изделие и его назначение'}</h2><p>${p.series==='Олимпика'?'Светильник «Олимпика» складывается из светодиодного модуля, монтажной рамки и драйвера. Линзы и аксессуары — дополнительные элементы. Эта карточка описывает отдельную товарную позицию; стоимость полного изделия определяется составом.':p.series==='Победа'?'Магнитная система 48 В объединяет светильники, шинопроводы, элементы питания, соединения и управление. Они заказываются отдельными позициями. Исполнения Про и Эко различаются конструктивом и геометрией.':'Название и товарная сущность приведены по продуктовой матрице ChampionLED. Состав исполнения и технические параметры уточняются по документации.'}</p><p>${p.power?esc(p.liveName):esc(p.name)+' — '+esc(p.type||p.category)+'.'}</p><p>Если требуется определить конфигурацию по плану, выбрать мощность, оптику, питание или управление под объект, задачу ведёт LEDMONSTER.</p></div>`}
const docs=[['Победа Про','Обзор линейки','pobeda-pro.pdf','Про и Эко — исполнения линейки «Победа»'],['Победа Про','Инструкция','pobeda-pro-manual.pdf','Монтаж и устройство системы'],['Победа Эко','Обзор исполнения','pobeda-eco.pdf','Встраиваемый конструктив'],['Победа Эко','Инструкция','pobeda-eco-manual.pdf','Монтаж и устройство системы'],['Олимпика','Обзор линейки','olimpika.pdf','Модуль, рамка, драйвер и аксессуары'],['Олимпика','Инструкция','olimpika-manual.pdf','Состав и монтаж модульного изделия']];
function materials(){return `<div class="wrap">${crumb([['Документация']])}<div class="page-top"><p class="eyebrow">Технические материалы</p><h1 class="page-title">Разобраться в продукте.<br>Проверить состав.</h1><p class="page-intro">Обзоры и инструкции по конкретным системам. Облегчённые копии документов из предоставленного пакета доступны для просмотра и скачивания.</p></div><div class="chips" id="doc-chips"><button class="chip active" data-doc="all">Все материалы</button><button class="chip" data-doc="Победа">Победа</button><button class="chip" data-doc="Олимпика">Олимпика</button></div><div style="overflow-x:auto"><table class="materials-table"><thead><tr><th>Серия / исполнение</th><th>Материал</th><th>Содержание</th><th>Файл</th></tr></thead><tbody id="doc-rows">${docRows()}</tbody></table></div><p class="notice">Состав и актуальность файлов проверяются по нужному исполнению. Материалы для будущих позиций, IES и 3D не обещаны для всего каталога.</p><section class="section">${projectBlock()}</section></div>`}
function docRows(filter='all'){return docs.filter(d=>filter==='all'||d[0].includes(filter)).map(d=>`<tr><td>${d[0]}</td><td>${d[1]}</td><td>${d[3]}</td><td><a href="docs/${d[2]}" target="_blank" rel="noopener">Открыть PDF ↗</a></td></tr>`).join('')}
function about(){return `<div class="wrap">${crumb([['О бренде']])}<section class="series-hero"><div><p class="eyebrow">Собственная товарная марка</p><h1 class="page-title">Профессиональная<br>основа.<br>В серийном продукте.</h1><p class="page-intro">ChampionLED — функциональные светильники, системы и компоненты с инженерной проработкой, качественными комплектующими и доступной ценой.</p></div><img src="assets/1-backgroundImage.webp" alt="Функциональное освещение в интерьере"></section><section class="section"><div class="article"><h2>Ценность формируется до покупки</h2><p>Опыт команды LEDMONSTER учтён при подготовке типовых решений. Требования к конструкции, компонентам и исполнениям формируются заранее. Продукция выпускается на контрактном производстве по требованиям бренда и проходит контроль на производстве и при приёмке партии.</p><h2>У доступности есть конструктивная основа</h2><p>Оптимизация конструкции, унификация компонентов и повторяемые производственные процессы помогают управлять стоимостью. Покупатель оценивает конкретный состав, параметры и цену полного изделия или системы.</p><h2>Ответственность сохраняется после покупки</h2><p>ChampionLED отвечает за продукцию под своей маркой. Гарантия на изделия — 3 года. Порядок обращения и упрощённой замены неисправного изделия определяется гарантийными условиями.</p></div></section>${projectBlock()}<section class="section">${sectionHead('Изучите ассортимент','От типа продукта — к линейке')}<div class="series-grid">${series.map(seriesTile).join('')}</div></section></div>`}
const roles={dealer:{label:'Дилерам и торговым партнёрам',title:'Продуманный ассортимент<br>для вашего предложения.',lead:'Стандартные светильники и системы с понятными артикулами, товарными материалами и технической основой.',items:[['Ассортимент для перепродажи','Собственные линейки и компоненты для жилых и коммерческих пространств.'],['Данные о продукте','Артикулы, назначения, исполнения и документация по конкретным сериям.'],['Коммерческие условия','Согласуются по формату сотрудничества и составу закупки. Размер скидки и условия образцов не назначаются автоматически.']],cta:'Обсудить сотрудничество',side:'Уже есть список позиций?',sideText:'Соберите артикулы и количество в каталоге. Для готового перечня ChampionLED оформляет товарную закупку.'},designer:{label:'Дизайнерам и архитекторам',title:'Типовые решения.<br>Данные для спецификации.',lead:'Изучайте внешний вид, исполнения и состав продукта. Определяйте позиции по каталогу и документации для включения в свой проект.',items:[['Каталожные исполнения','Сопоставляйте модель, монтаж, световые параметры и состав полного изделия.'],['Материалы по серии','Инструкции и обзоры доступны в разделе документации. Наличие чертежей, фотометрии и 3D уточняется по позиции.'],['Переход к проектной работе','Когда требуется подбор, расчёт, конфигурация или сопровождение — задачу ведёт LEDMONSTER.']],cta:'Запросить сведения по артикулам',side:'Нужна работа по плану?',sideText:'Передайте задачу LEDMONSTER: команда поможет проработать световое решение с учётом объекта.'},installer:{label:'Подрядчикам и интеграторам',title:'Техническая ясность<br>до начала монтажа.',lead:'Изучайте состав, схемы, питание и управление по материалам конкретной системы. Закупайте определённые позиции по готовой спецификации.',items:[['Состав поставки','Артикулы, количество, питание и монтажные элементы определяются до оформления.'],['Монтажные материалы','Используйте инструкцию соответствующей серии и исполнения. Совместимость разных систем не предполагается автоматически.'],['Индивидуальные вопросы','Проверка конфигурации под объект, подбор питания или управления и все тендерные задачи — в LEDMONSTER.']],cta:'Запросить условия поставки',side:'Есть готовая спецификация?',sideText:'Найдите позиции по артикулам, укажите количество и подготовьте товарный запрос.'}};
function professionals(key='dealer'){const r=roles[key]||roles.dealer;return `<div class="wrap">${crumb([[r.label]])}<section class="section role-hero" style="padding-top:10px"><div><p class="eyebrow">Профессиональное сотрудничество</p><h1>${r.title}</h1><p>${r.lead}</p><div class="role-list">${r.items.map(([t,d])=>`<div><h3>${t}</h3><p>${d}</p></div>`).join('')}</div><button class="button primary" style="margin-top:28px" data-lead="${key}">${r.cta} ↗</button></div><aside class="role-aside"><h2>${r.side}</h2><p>${r.sideText}</p>${btn(key==='designer'?'Перейти к LEDMONSTER':'Перейти в каталог',key==='designer'?'#/project':'#/catalog','dark')}<p class="fine" style="margin-top:30px">Действующие партнёры LEDMONSTER продолжают работу через LEDMONSTER, включая закупку изделий ChampionLED.</p></aside></section><section class="section">${sectionHead('Полезные материалы','Начните с продукта')}<div class="series-grid">${series.map(seriesTile).join('')}</div></section></div>`}
function leadForm(kind='order'){const project=kind==='project',partner=kind==='dealer';return `<form class="form" data-lead-form="${esc(kind)}"><p class="form-hint">Демонстрационная форма. Данные не сохраняются и не отправляются.</p><div class="form-pair"><label>Как к вам обращаться<input name="name" autocomplete="name" required placeholder="Имя"></label><label>Телефон<input name="phone" type="tel" autocomplete="tel" required placeholder="+7 (___) ___-__-__"></label><label>Почта для ответа<input name="email" type="email" autocomplete="email" required placeholder="name@company.ru"></label></div>${partner?'<label>Компания и формат работы<input name="company" required placeholder="Салон света, магазин, торговая компания"></label>':''}<label>${project?'Ваша задача':'Артикулы и вопрос'}<textarea name="message" required placeholder="${project?'Что требуется: подбор, расчёт, конфигурация или реализация?':'Укажите позиции и количество либо задайте вопрос о продукте.'}"></textarea></label><label class="check"><input type="checkbox" name="consent" required><span>Согласен на обработку введённых данных для демонстрации формы.</span></label><button class="button primary" type="submit">${project?'Подготовить проектный запрос':'Подготовить запрос'} <span>↗</span></button></form>`}
function project(){return `<div class="wrap">${crumb([['Проектная работа LEDMONSTER']])}<section class="section role-hero" style="padding-top:12px"><div><p class="eyebrow">От товара — к задаче объекта</p><div class="project-logo">LED<span>MONSTER</span></div><h1>Нужен свет<br>под ваш проект?</h1><p>Подбор, светотехнический расчёт, конфигурация системы, адаптация и реализация — работа проектной команды LEDMONSTER.</p><div class="role-list"><div><h3>Что подготовить</h3><p>План, описание помещений, требования к свету, сроки и бюджет — в той мере, в которой они уже известны.</p></div><div><h3>Что сохраняется</h3><p>Продукция ChampionLED остаётся под своей маркой с гарантией 3 года. Состав проектных работ и их условия согласуются отдельно.</p></div></div><p style="font-size:11px;margin-top:25px"><a class="textlink" href="https://ledmonster.ru/send-project/" target="_blank" rel="noopener">Открыть обращение на сайте LEDMONSTER ↗</a></p></div><div class="role-aside"><h2>Начните с задачи</h2>${leadForm('project')}</div></section></div>`}
function cartPage(){const entries=Object.entries(cart).map(([id,n])=>[P.find(p=>p.id===id),n]).filter(([p,n])=>p&&n>0);const subtotal=entries.reduce((a,[p,n])=>a+(p.price||0)*n,0),unknown=entries.filter(([p])=>!p.price).length;return `<div class="wrap">${crumb([['Список заказа']])}<h1 class="page-title">Список заказа</h1><p class="page-intro">Определённые позиции и количество. Актуальные цена, наличие и условия поставки подтверждаются при оформлении.</p><section class="section" style="padding-top:15px">${entries.length?entries.map(([p,n])=>`<div class="cart-row">${p.images?`<img src="${p.images[0]}" alt="${esc(p.name)}">`:'<div class="no-photo">⊙</div>'}<div><a href="#/product/${p.id}"><h3>${esc(p.short||p.name)}</h3></a><small>${esc(p.liveSku||p.sku)} · ${esc(p.series)}</small></div><div class="quantity"><button data-cart-minus="${p.id}" aria-label="Уменьшить количество">−</button><output>${n}</output><button data-cart-plus="${p.id}" aria-label="Увеличить количество">+</button></div><strong>${p.price?rub(p.price*n):'По запросу'}</strong><button class="remove" data-remove="${p.id}" aria-label="Удалить позицию">×</button></div>`).join('')+`<div class="cart-total"><div><h2>${rub(subtotal)}</h2><small>Сумма позиций с указанной ценой${unknown?` · ещё ${unknown} поз. по запросу`:''}<br>Предварительно, по снимку цен 01.11.2026</small></div><div class="actions"><button class="button" data-action="export">Скачать CSV ↓</button><button class="button primary" data-action="order-request">Подготовить запрос ↗</button></div></div><p class="notice">Это интерактивный прототип. Оплата и отправка заказа отключены. Список хранится только в вашем браузере.</p>`:`<div class="empty"><h2>Пока нет позиций</h2><p>Добавьте нужные артикулы из каталога.</p>${btn('Перейти в каталог','#/catalog')}</div>`}</section></div>`}
function favorites(){const ps=P.filter(p=>favs.includes(p.id));return `<div class="wrap">${crumb([['Избранное']])}<h1 class="page-title">Избранное</h1><section class="section">${ps.length?`<div class="product-grid">${ps.map(productCard).join('')}</div>`:`<div class="empty"><h2>Сохраните позиции для возвращения</h2><p>Нажмите ♡ на карточке товара.</p>${btn('Открыть каталог','#/catalog')}</div>`}</section></div>`}
function comparePage(){const ps=compare.map(id=>P.find(p=>p.id===id)).filter(Boolean);return `<div class="wrap">${crumb([['Сравнение']])}<h1 class="page-title">Сравнение светильников</h1><section class="section">${ps.length?`<div class="comparison"><table><thead><tr><th>Модели «Победа»</th>${ps.map(p=>`<th><a href="#/product/${p.id}"><img src="${p.images[0]}" alt="${esc(p.short)}"><br>${esc(p.short)}</a></th>`).join('')}</tr></thead><tbody>${[['Артикул',p=>p.sku],['Мощность',p=>p.power+' Вт'],['Температура',p=>'3000 / 4000 К'],['Система',p=>'Победа · 48 В'],['Исполнение',p=>'Чёрный · ON-OFF'],['Цена на 01.11.2026',p=>rub(p.price)]].map(([name,get])=>`<tr><td>${name}</td>${ps.map(p=>`<td>${get(p)}</td>`).join('')}</tr>`).join('')}<tr><td>Действие</td>${ps.map(p=>`<td><button class="button" data-add="${p.id}">В заказ +</button></td>`).join('')}</tr></tbody></table></div><p class="notice">Сравниваются подтверждённые каталожные параметры. Для выбора светового решения под объект перейдите в LEDMONSTER.</p><button class="textlink" data-action="clear-compare">Очистить сравнение</button>`:`<div class="empty">Отметьте до трёх моделей в каталоге для сравнения.</div>`}</section></div>`}
function service(){return `<div class="wrap">${crumb([['Заказ, доставка и гарантия']])}<h1 class="page-title">От списка позиций — к поставке</h1><div class="steps-grid"><div><span>01</span><b>Определите артикулы</b><p>Каталог, документация и полный состав изделия.</p></div><div><span>02</span><b>Укажите количество</b><p>Соберите список заказа или передайте готовый перечень.</p></div><div><span>03</span><b>Согласуйте условия</b><p>Цена, наличие, срок, оплата и доставка — по конкретной поставке.</p></div><div><span>04</span><b>Получите продукцию</b><p>Изделия ChampionLED сохраняют марку и гарантию 3 года.</p></div></div><section class="section">${faqs([faq[0],faq[5],faq[4]])}</section><div class="actions">${btn('К каталогу','#/catalog')}<a class="textlink" href="https://championled.ru/delivery" target="_blank" rel="noopener">Действующие условия доставки ↗</a><a class="textlink" href="https://championled.ru/return" target="_blank" rel="noopener">Гарантийные условия ↗</a></div><div class="section"></div></div>`}
function contacts(){return `<div class="wrap">${crumb([['Контакты']])}<h1 class="page-title">Обсудим товарный заказ</h1><section class="section contact-grid"><div><p class="eyebrow">ChampionLED</p><h2><a href="tel:+78003503085">8 800 350-30-85</a></h2><p><a class="textlink" href="mailto:order@championled.ru">order@championled.ru ↗</a></p><h2>Офис в Москве</h2><address>3-й Красносельский переулок, 19с11<br>Метро «Красносельская»<br>По будням 10:00–18:00<br>+7 495 109-23-00</address><p class="fine">Контакты сверены с действующим сайтом ChampionLED 01.11.2026.</p><a class="textlink" href="#/project">Подбор, расчёт и реализация — LEDMONSTER ↗</a></div><div>${leadForm('order')}</div></section></div>`}
function review(){modal(`<p class="eyebrow">Версия для обсуждения · 01.11.2026</p><h2>Продуктовая витрина<br>на основе новых документов</h2><div class="review-grid"><div><h3>Что заложено в прототип</h3><ul><li>Master v0.1: категории, линейки, модели, компоненты, артикулы и статусы.</li><li>Бренд-платформа, ЦА и УТП из присланного пакета. Текст трёх DOCX совпадает с проектной редакцией от 28.10.2026.</li><li>Никаких обещаний наличия всего ассортимента, общей совместимости и автоматических дилерских скидок.</li><li>Каталог для самостоятельной закупки; проектная работа — LEDMONSTER.</li></ul></div><div><h3>Перенос в Яндекс.Кит</h3><ul><li>Текущее меню: точные ветки, названия, вложенность и порядок сохранены по снимку живого сайта.</li><li>Hero, сетки серий, преимущества, состав системы, FAQ и CTA — кастомные секции.</li><li>Поиск, фильтры, избранное, предложения и заказ — через возможности платформы.</li><li>JS этого прототипа моделирует поведение, он не вставляется в Mystique-секции.</li></ul></div></div><p>Новые линейки со статусами «в пути», «планируется» или «требует решения» не показаны как доступные к покупке. Изображения взяты с действующего сайта и не представлены как новые реализованные проекты.</p><p><a class="textlink" href="https://championled.ru" target="_blank" rel="noopener">Источник структуры меню и цен: championled.ru ↗</a></p>`)}
function notFound(){return `<div class="wrap section"><h1 class="page-title">Страница не найдена</h1>${btn('На главную','#/')}</div>`}
function render(){const path=location.hash.slice(1)||'/';const [r,query]=path.split('?'),parts=r.split('/').filter(Boolean);let html;closeMenu();limit=12;filters={};$('#search').value='';switch(parts[0]){case undefined:html=home();break;case 'catalog':html=catalog(parts[1]);break;case 'search':{const q=new URLSearchParams(query).get('q')||'';$('#search').value=q;html=catalog(null,q);break}case 'series':html=seriesPage(parts[1]);break;case 'product':html=productPage(parts[1]);break;case 'materials':html=materials();break;case 'about':html=about();break;case 'professionals':html=professionals(parts[1]);break;case 'project':html=project();break;case 'cart':html=cartPage();break;case 'favorites':html=favorites();break;case 'compare':html=comparePage();break;case 'faq':html=`<div class="wrap">${crumb([['Вопросы и ответы']])}<h1 class="page-title">Перед выбором и заказом</h1><section class="section">${faqs()}</section></div>`;break;case 'service':html=service();break;case 'contacts':html=contacts();break;default:html=notFound()}$('#main').innerHTML=html;document.title=($('#main h1')?.innerText||'Функциональный свет с инженерной основой').replace(/\s+/g,' ')+' — ChampionLED';counts();updateListing();compareBar();window.scrollTo(0,0)}
function compareBar(){$('.compare-bar')?.remove();if(compare.length&&!location.hash.includes('/compare')){const el=document.createElement('div');el.className='compare-bar';el.innerHTML=`<span>Для сравнения: ${compare.length} / 3</span><a class="button" href="#/compare">Сравнить ↗</a><button data-action="clear-compare" aria-label="Очистить сравнение">×</button>`;document.body.append(el)}}
function menuLink(n,cls=''){const slug=n.url.replace('https://championled.ru','').split('/').pop();const href=n.url.includes('/catalog/')?'#/catalog/'+slug:'#/series/pobeda';return `<a class="${cls}" href="${href}" data-source-url="${esc(n.url)}">${esc(n.title)}</a>`}
function closeMenu(){$('#mega').hidden=true;$('.catalog-toggle').setAttribute('aria-expanded','false')}
function toggleMenu(){const el=$('#mega');if(!el.hidden){closeMenu();return}const [root,standalone,categories]=DATA.menu;el.innerHTML=`<div class="mega-inner mega"><div class="wrap"><div class="mega-head"><p>Каталог ChampionLED · текущая структура меню</p><button data-action="menu" aria-label="Закрыть меню">Закрыть ×</button></div><div class="mega-columns"><div>${menuLink(root,'root-title')}<div class="mega-systems">${root.children.map(n=>`<div><h4>${menuLink(n)}</h4>${n.children.map(c=>menuLink(c)).join('')}</div>`).join('')}</div><div class="standalone">${menuLink(standalone)}</div></div><div>${menuLink(categories,'root-title')}${categories.children.map(n=>`<h4>${menuLink(n)}</h4>${n.children.map(c=>menuLink(c)).join('')}`).join('')}<div style="margin-top:25px">${btn('Весь каталог','#/catalog','')}</div></div></div></div></div>`;el.hidden=false;$('.catalog-toggle').setAttribute('aria-expanded','true')}
function exportCart(){const rows=[['Артикул','Наименование','Количество','Цена за единицу, руб. (01.11.2026)','Сумма, руб.','Статус цены']];for(const [id,n]of Object.entries(cart)){const p=P.find(x=>x.id===id);if(p)rows.push([p.liveSku||p.sku,p.liveName||p.name,n,p.price||'',p.price?p.price*n:'',p.price?'Снимок цены; требуется подтверждение':'По запросу'])}download('ChampionLED-список-заказа.csv','\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(';')).join('\r\n'));toast('Список заказа скачан в CSV')}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.getAttribute('href')==='#main'){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return}const d=b.dataset;
 if(d.action==='menu')toggleMenu();if(d.action==='close')closeModal();if(d.action==='review')review();
 if(d.action==='qty-minus'||d.action==='qty-plus'){qty=Math.min(999,Math.max(1,qty+(d.action==='qty-plus'?1:-1)));$('#qty').textContent=qty}
 if(d.add)add(d.add);if(d.addQty)add(d.addQty,qty);
 if(d.fav){const active=favs.includes(d.fav);favs=active?favs.filter(id=>id!==d.fav):[...favs,d.fav];persist();toast(active?'Удалено из избранного':'Сохранено в избранном');if(location.hash.startsWith('#/favorites'))$('#main').innerHTML=favorites();else $$(`[data-fav="${d.fav}"]`).forEach(x=>{x.classList.toggle('active',!active);x.setAttribute('aria-pressed',String(!active));x.textContent=x.classList.contains('favourite')?(!active?'♥':'♡'):(!active?'♥ В избранном':'♡ Сохранить в избранное')})}
 if(d.action==='filters')$('#filters').classList.toggle('open');if(d.action==='more'){limit+=12;updateListing()}
 if(d.action==='reset-filters'){filters={};$$('#filters input').forEach(i=>i.checked=false);if($('#filters select'))$('#filters select').value='';limit=12;updateListing()}
 if(d.image){$('#gallery').innerHTML=`<img src="${d.image}" alt="Фотография товара">`;$$('.thumbs button').forEach(x=>x.classList.toggle('active',x===b))}
 if(d.tab){$$('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))});$('#product-tab').innerHTML=productTab(P.find(p=>p.id===d.product),d.tab)}
 if(d.doc){$$('[data-doc]').forEach(x=>x.classList.toggle('active',x===b));$('#doc-rows').innerHTML=docRows(d.doc)}
 if(d.cartMinus||d.cartPlus){const id=d.cartMinus||d.cartPlus;cart[id]=Math.min(999,Math.max(1,cart[id]+(d.cartPlus?1:-1)));persist();$('#main').innerHTML=cartPage()}
 if(d.remove){delete cart[d.remove];persist();$('#main').innerHTML=cartPage()}
 if(d.action==='export')exportCart();if(d.action==='clear-compare'){compare=[];$$('[data-compare]').forEach(i=>i.checked=false);compareBar();if(location.hash.startsWith('#/compare'))$('#main').innerHTML=comparePage()}
 if(d.lead)modal(`<h2>${roles[d.lead]?.cta||'Сведения о заказе'}</h2>${leadForm(d.lead)}`);
 if(d.action==='order-request')modal(`<h2>Запрос по готовому списку</h2><p>Позиций: ${Object.keys(cart).length}. После согласования — актуальные цена, наличие, сроки и условия.</p>${leadForm('order')}`);
});
document.addEventListener('change',e=>{const d=e.target.dataset;if(d.filter){filters[d.filter]=e.target.type==='checkbox'?e.target.checked:e.target.value;limit=12;updateListing()}if(d.power){filters.power=$$('[data-power]:checked').map(i=>Number(i.dataset.power));limit=12;updateListing()}if(e.target.id==='sort')updateListing();if(d.compare){if(e.target.checked&&compare.length>=3){e.target.checked=false;toast('Можно сравнить до трёх моделей');return}compare=e.target.checked?[...compare,d.compare]:compare.filter(id=>id!==d.compare);compareBar()}});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();const q=$('#search').value.trim();if(q){const h='#/search?q='+encodeURIComponent(q);if(location.hash===h)render();else location.hash=h}}if(e.target.matches('[data-lead-form]')){e.preventDefault();const kind=e.target.dataset.leadForm;const box=document.createElement('div');box.innerHTML=`<span class="status">Демонстрация завершена</span><h2 style="font-size:25px;margin-top:18px">Запрос подготовлен.</h2><p style="font-size:12px">${kind==='project'?'Маршрут — проектная команда LEDMONSTER.':'Маршрут — товарный заказ ChampionLED.'} Данные не отправлены и не сохранены.</p>${kind==='order'?'<button class="button" data-action="export">Скачать список заказа CSV ↓</button>':btn('Продолжить знакомство с каталогом','#/catalog','')}`;e.target.replaceWith(box);box.querySelector('a')?.addEventListener('click',()=>{if($('#modal').open)closeModal()})}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});document.addEventListener('click',e=>{if(!e.target.closest('header'))closeMenu()});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});window.addEventListener('hashchange',()=>{if($('#modal').open)closeModal();render()});render();
